/**
 * Inside the signed-in app, both language switches (phone header and desktop sidebar) save the
 * choice to the account; LanguageToggle only does so when given `persist` (ISSUE-006).
 *
 * Value: protects=a signed-in language switch reaches PUT /auth/me from both the header and the
 * sidebar toggle; fails_when=`persist` is dropped from either LanguageToggle in this layout;
 * why_new=language-toggle.test sets persist itself, nothing checks the app passes it; seam=none
 * Generated by /ship test coverage audit (pass 1).
 */
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { I18nProvider } from "@/lib/i18n";
import AuthenticatedLayout from "./layout";

const mockGet = jest.fn();
const mockPut = jest.fn();
jest.mock("@/lib/api-client", () => ({
  api: {
    get: (...args: unknown[]) => mockGet(...args),
    post: jest.fn(),
    put: (...args: unknown[]) => mockPut(...args),
  },
}));
jest.mock("next/navigation", () => ({
  useRouter: () => ({ push: jest.fn() }),
  usePathname: () => "/dashboard",
}));

const account = { id: "u1", email: "a@b.co", role: "investor", locale: "en" };

beforeEach(() => {
  mockGet.mockReset().mockImplementation((path: string) =>
    Promise.resolve(path === "/auth/me" ? account : null)
  );
  mockPut.mockReset().mockResolvedValue({});
  localStorage.clear();
  localStorage.setItem("token", "t");
  document.documentElement.lang = "en";
  document.cookie = "locale=; max-age=0; path=/";
});

it("saves a language switch to the account from the header and from the sidebar", async () => {
  render(
    <I18nProvider initialLocale="en">
      <AuthenticatedLayout>
        <main />
      </AuthenticatedLayout>
    </I18nProvider>
  );
  const user = userEvent.setup();

  const [headerToggle, sidebarToggle] = await screen.findAllByRole("button", { name: "Passer en français" });
  await user.click(headerToggle);
  expect(mockPut).toHaveBeenLastCalledWith("/auth/me", { locale: "fr" }, { stayOnUnauthorized: true });

  // Both switches follow the interface: the sidebar one now offers English
  expect(sidebarToggle).toHaveAccessibleName("Switch to English");
  await user.click(sidebarToggle);
  expect(mockPut).toHaveBeenLastCalledWith("/auth/me", { locale: "en" }, { stayOnUnauthorized: true });
  expect(mockPut).toHaveBeenCalledTimes(2);
});
